<?php require_once __DIR__.'/includes/bootstrap.php';require_login();$user=current_user($pdo);$errors=[];$name=$user['full_name'];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['full_name']??'');if(mb_strlen($name)<2||mb_strlen($name)>100)$errors[]='Name must be between 2 and 100 characters.';try{$pic=upload_profile_picture();if(!$errors){if($pic){$s=$pdo->prepare('UPDATE users SET full_name=?,profile_picture=? WHERE id=?');$s->execute([$name,$pic,$_SESSION['user_id']]);}else{$s=$pdo->prepare('UPDATE users SET full_name=? WHERE id=?');$s->execute([$name,$_SESSION['user_id']]);}flash('success','Your profile has been updated.');redirect('/profile.php');}}catch(RuntimeException $ex){$errors[]=$ex->getMessage();}}$user=current_user($pdo);$page_title='My profile';require __DIR__.'/includes/header.php'; ?>
<div class="profile-layout"><section class="panel form-panel"><h1>My Profile</h1><div class="profile-large"><img src="<?= avatar($user) ?>" alt="Profile picture"><div><h2><?= e($user['full_name']) ?></h2><p><?= e($user['email']) ?></p><small>Member since <?= e(date('d M Y',strtotime($user['created_at']))) ?></small></div></div><hr><h2>Update profile</h2><?php foreach($errors as $err): ?><div class="alert error"><?= e($err) ?></div><?php endforeach; ?><form method="post" enctype="multipart/form-data" data-validate><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><label>Full name<input name="full_name" required minlength="2" maxlength="100" value="<?= e($name) ?>"></label><label>New profile picture <span class="muted">(optional)</span><input type="file" name="profile_picture" accept="image/jpeg,image/png,image/webp" data-image-input></label><img class="image-preview hidden" data-image-preview alt="New profile picture preview"><button class="button primary" type="submit">Save Profile</button></form></section></div><?php require __DIR__.'/includes/footer.php'; ?>